162	
163	    /**
164	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
165	     */
166	    @Transient
167	    public String getDisplayName() {
168	        return this.getLastName() + ", " + this.getFirstName();
169	    }
